var l = ["<script", ' type="application/ld+json">', "<\/script>"], c = ["<nav", ' style="', '"><a href="/"><img src="/logo_cmi.png" alt="Creative Metal Industries" width="140" height="71"></a><div style="', '"></div><a href="/blog" style="', '">\u2190 All Articles</a></nav>'], g = ["<div", ' style="', '"><a href="/" style="', '">Home</a><span style="', '">\u203A</span><a href="/blog" style="', '">Blog</a><span style="', '">\u203A</span><span>SA 516 Carbon Steel Plate Guide</span></div>'], f = ["<main", ' style="', '"><div style="', '"><span style="', '">Material Guide</span><span style="', '">June 2026 \xB7 9 min read</span><h1 style="', '">Carbon Steel SA 516 Plate \u2014 The Pressure Vessel and Boiler Standard</h1><p style="', '">If you fabricate pressure vessels, boilers, or storage tanks in India, you already know <strong>SA 516</strong>. This ASTM/ASME specification has been the undisputed standard for moderate and lower-temperature pressure vessel plates for over 50 years. As a leading <strong>carbon steel SA 516 plate stockist in India</strong> and <strong>steel trading company in Gujarat</strong>, Creative Metal Industries maintains ready stock of SA 516 Grade 60 and Grade 70 plates from 6mm to 200mm thickness \u2014 with IBR Form III-C, NACE MR-01-75 compliance, and HIC test reports available for every heat.</p></div><h2 style="', '">Why SA 516 is the Go-To Plate for Pressure Vessels</h2><p style="', '">Three factors make SA 516 the default choice for ASME Section VIII coded vessels:</p><ul style="', '"><li><strong>Excellent weldability:</strong> Low carbon equivalent (CE \u2264 0.45) means no preheat required for plates up to 40mm. Multi-pass welds are routine without PWHT concerns</li><li><strong>Good notch toughness:</strong> When normalised, SA 516 provides reliable Charpy impact values at temperatures down to -40\xB0C \u2014 critical for cryogenic storage and cold-climate installations</li><li><strong>Optimal strength-to-cost ratio:</strong> Grade 70 (485-620 MPa tensile, 260 MPa yield) offers sufficient strength for most vessel designs without the premium of alloy or quenched-tempered grades</li><li><strong>Universal availability:</strong> Every major Indian mill (SAIL, AMNS, TATA, JSW) produces it. Multiple sources = competitive pricing and short lead times</li><li><strong>Code acceptance:</strong> Explicitly listed in ASME BPVC Section II Part A as SA-516. No supplementary requirements needed for standard applications</li></ul><h2 style="', '">Chemical Composition \u2014 SA 516 Gr.70</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Element</th><th style="', '">Thickness \u2264 12.5mm</th><th style="', '">12.5\u201350mm</th><th style="', '">50\u2013200mm</th><th style="', '">Role</th></tr></thead><tbody>', '</tbody></table></div><p style="', '">Note: For HIC-resistant SA 516, sulphur is further restricted to \u2264 0.002% with calcium treatment for inclusion shape control. This is the <strong>NACE HIC</strong> variant supplied by us as a specialist <strong>NACE HIC steel plate supplier in India</strong>.</p><h2 style="', '">Mechanical Properties \u2014 SA 516 Grades Compared</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Property</th><th style="', '">Gr.60</th><th style="', '">Gr.65</th><th style="', '">Gr.70</th></tr></thead><tbody>', '</tbody></table></div><h2 style="', '">Key Applications</h2><div style="', '">', '</div><h2 style="', '">Grades Explained \u2014 When to Use Gr.60, 65, or 70</h2><ul style="', '"><li><strong>SA 516 Grade 60:</strong> For low/moderate-pressure vessels, large storage tanks (API 650), and applications where maximum weldability is prioritised over strength. Rarely specified in new designs \u2014 Grade 70 has largely replaced it.</li><li><strong>SA 516 Grade 65:</strong> Intermediate grade \u2014 seldom used in India. Most designers jump directly to Gr.70 for the marginal strength increase with no weldability penalty.</li><li><strong>SA 516 Grade 70:</strong> The workhorse \u2014 accounts for ~80% of all SA 516 consumption. Suitable for ASME Section VIII vessels up to 650\xB0F (343\xB0C) design temperature. When normalised, provides excellent impact toughness for cold service down to -40\xB0C.</li></ul><h2 style="', '">Why Source SA 516 from Creative Metal Industries?</h2><ul style="', '"><li><strong>Ready stock:</strong> SA 516 Gr.60/70 from 6mm to 150mm at our Vadodara warehouse \u2014 2-3 day delivery for standard sizes</li><li><strong>IBR Form III-C:</strong> Mandatory for Indian boiler fabrication \u2014 we stock IBR-certified plates from SAIL and AMNS approved mills</li><li><strong>NACE/HIC certified:</strong> For sour service \u2014 S \u2264 0.002%, Ca-treated, HIC tested per TM-0284 (CLR \u2264 15%, CTR \u2264 5%, CSR \u2264 2%)</li><li><strong>UT tested:</strong> 100% ultrasonic tested per SA 435 Level B or SA 578 Level B \u2014 zero lamination guarantee</li><li><strong>Cut-to-size:</strong> Oxy-fuel and plasma cutting at our facility \u2014 deliver plate to your exact dimensions</li><li><strong>Mill sources:</strong> SAIL (Bhilai, Bokaro), AMNS (ArcelorMittal Nippon Steel), TATA Steel, JSW \u2014 all with original MTC (EN 10204 3.1/3.2)</li></ul><p style="', '">For detailed pricing, stock availability, and specifications, visit our dedicated product page: <a href="/carbon-steel-sa516-plate-stockist-india" style="', '">SA 516 Plate Stockist India \u2192</a></p><h2 style="', '">Frequently Asked Questions \u2014 SA 516</h2><div style="', '">', '</div><div style="', '"><h2 style="', '">Need SA 516 Plates?</h2><p style="', '">Ready stock 6mm-150mm. IBR + NACE + HIC. SAIL, AMNS, TATA mills. Same-day quotes.</p><div style="', '"><a href="tel:+919998280619" style="', '">\u{1F4DE} +91 99982 80619</a><a href="https://wa.me/919998280619" target="_blank" rel="noopener" style="', '">\u{1F4AC} WhatsApp</a><a href="/carbon-steel-sa516-plate-stockist-india" style="', '">View Stock & Prices \u2192</a></div></div><h3 style="', '">Related Articles & Products</h3><div style="', '">', "</div></main>"], h = ["<footer", ' style="', '"><p><strong style="', '">Creative Metal Industries</strong> \u2014 Carbon Steel SA 516 Plate Stockist India | Steel Trading Company Gujarat</p><p><a href="tel:+919998280619" style="', '">+91 99982 80619</a> | <a href="https://www.creativemetalind.com" style="', '">creativemetalind.com</a></p></footer>'], u = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], b = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], y = ["<div", ' style="', '"><span style="', '">', '</span><h3 style="', '">', '</h3><p style="', '">', "</p></div>"], A = ["<details", ' style="', '"><summary style="', '">', '</summary><p style="', '">', "</p></details>"], S = ["<a", ' style="', '"><!--$-->', "<!--/--> \u2192</a>"];
const w = JSON.stringify({ "@context": "https://schema.org", "@type": "Article", headline: "Carbon Steel SA 516 Plate \u2014 The Pressure Vessel and Boiler Standard", author: { "@type": "Organization", name: "Creative Metal Industries" }, publisher: { "@type": "Organization", name: "Creative Metal Industries", logo: { "@type": "ImageObject", url: "https://www.creativemetalind.com/logo_cmi.png" } }, datePublished: "2026-06-17", image: "https://www.creativemetalind.com/img/carbon-steel-plate.webp", url: "https://www.creativemetalind.com/blog/sa-516-carbon-steel-plate-guide" }), v = JSON.stringify({ "@context": "https://schema.org", "@type": "FAQPage", mainEntity: [{ "@type": "Question", name: "What is SA 516 Grade 70 used for?", acceptedAnswer: { "@type": "Answer", text: "SA 516 Grade 70 is used for fabricating pressure vessels, boilers, heat exchangers, storage tanks (API 650/620), reactors, and columns in petroleum refining, petrochemical, fertilizer, and power generation industries. It is the most widely specified plate for ASME Section VIII coded vessels due to its combination of strength (485-620 MPa tensile), weldability, and notch toughness." } }, { "@type": "Question", name: "What is the difference between SA 516 Grade 60 and Grade 70?", acceptedAnswer: { "@type": "Answer", text: "The primary difference is tensile strength: Gr.60 has 415-550 MPa while Gr.70 has 485-620 MPa. Gr.70 is preferred for higher-pressure vessels and thicker sections. Both are readily weldable. Gr.60 is used for lower-pressure storage tanks and applications where design stress is not critical. Gr.70 accounts for approximately 80% of all SA 516 consumption." } }, { "@type": "Question", name: "Can SA 516 plates be supplied with NACE and HIC testing?", acceptedAnswer: { "@type": "Answer", text: "Yes. Creative Metal Industries stocks SA 516 Gr.60/70 plates in NACE MR-01-75 compliant condition with HIC (Hydrogen Induced Cracking) testing per NACE TM-0284. Acceptance criteria: CLR \u2264 15%, CTR \u2264 5%, CSR \u2264 2%. These are mandatory for sour service (H\u2082S) applications in oil & gas refineries and offshore platforms. We also supply with SSC testing per TM-0177 on request." } }] });
